_LSHAPES = [[], ["a"], ["a", "b"], ["a", "b", "c"], ["a", "b", "c", "d"], ["N"], ["a", "N", "b"]]


def _largs(i, with_null):
    sh = _LSHAPES[i]
    letters = [c for c in "abc" if c in sh] + (["d"] if "d" in sh else [])
    out = [f"$t{c}{i}" for c in letters]
    if "d" not in sh:
        out.append(f"$td{i}")
    if with_null:
        out.append(0)
    return out


def _lstate(n, objsz):
    return ([(f"$o{i}", 0, objsz) for i in range(n)] + [(f"$t{i}", 0, 0x340) for i in range(n)] + [(f"$n{i}", 0, 0x80) for i in range(n)] + [_FREELOG])


